import { ECOLOGY_POPULATION_LEVELS, ECOLOGY_PRESETS, ECOLOGY_PRESET_POPULATIONS, SPECIES, SPECIES_IDS, ecologyPresetCounts, foodPreferenceSummary, isSustainableForage, spatialEcology } from "./species-registry.js";
import { BEHAVIOUR_ONTOLOGY } from "./behaviour-ontology.js";
import { ACTION_PRESENTATION } from "./action-state.js";
