const normalizeReferenceSearchText = (value) => String(value ?? "")
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&(?:nbsp|ensp|emsp);/gi, " ")
  .replace(/&amp;/gi, " and ")
  .replace(/&[a-z0-9#]+;/gi, " ")
  .toLowerCase()
  .replace(/[^a-z0-9.-]+/g, " ")
  .trim()
  .replace(/\s+/g, " ");

let defaultReferenceSearchIndex = null, defaultReferenceHtml = null, defaultReferenceById = null;
const referenceCacheMetrics = { searchIndexBuilds: 0, searchIndexHits: 0, htmlBuilds: 0, htmlHits: 0, sectionMapBuilds: 0 };

export function buildLaboratoryReferenceSearchIndex(sections = LABORATORY_REFERENCE_SECTIONS) {
  if (!Array.isArray(sections)) throw new TypeError("Reference search index expects an array of sections");
  return Object.freeze(sections.map((section, index) => {
    const id = String(section?.id || "");
    if (!id) throw new TypeError(`Reference section ${index} requires a non-empty id`);
    const title = String(section.title || ""), summary = String(section.summary || "");
    const titleText = normalizeReferenceSearchText(title), summaryText = normalizeReferenceSearchText(summary);
    const contentText = normalizeReferenceSearchText(section.html);
    return Object.freeze({ id, index, title, summary, titleText, summaryText, searchText: `${titleText} ${summaryText} ${contentText}`.trim() });
  }));
}

/** Lazily builds the expensive full-text index only when search needs it. */
export function laboratoryReferenceSearchIndex() {
  if (!defaultReferenceSearchIndex) { defaultReferenceSearchIndex = buildLaboratoryReferenceSearchIndex(); referenceCacheMetrics.searchIndexBuilds += 1; }
  else referenceCacheMetrics.searchIndexHits += 1;
  return defaultReferenceSearchIndex;
}

export function searchLaboratoryReference(query, { limit = Infinity } = {}) {
  const normalized = normalizeReferenceSearchText(query);
  if (!normalized) return Object.freeze([]);
  const terms = normalized.split(" ").filter(Boolean);
  const maximum = Number.isFinite(Number(limit)) ? Math.max(0, Math.floor(Number(limit))) : Infinity;
  const matches = laboratoryReferenceSearchIndex().filter((entry) => terms.every((term) => entry.searchText.includes(term))).map((entry) => {
    let score = entry.titleText.includes(normalized) ? 100 : entry.summaryText.includes(normalized) ? 50 : entry.searchText.includes(normalized) ? 20 : 0;
    for (const term of terms) score += entry.titleText.includes(term) ? 8 : entry.summaryText.includes(term) ? 4 : 1;
    return { entry, score };
  }).sort((left, right) => right.score - left.score || left.entry.index - right.entry.index);
  return Object.freeze(matches.slice(0, maximum).map(({ entry, score }) => Object.freeze({ id: entry.id, title: entry.title, summary: entry.summary, score })));
}

export function laboratoryReferenceSection(id) {
  if (!defaultReferenceById) { defaultReferenceById = new Map(LABORATORY_REFERENCE_SECTIONS.map((section) => [section.id, section])); referenceCacheMetrics.sectionMapBuilds += 1; }
  return defaultReferenceById.get(String(id)) || null;
}

export function laboratoryReferenceCacheMetrics() {
  return Object.freeze({
    ...referenceCacheMetrics,
    searchIndexEntries: defaultReferenceSearchIndex?.length || 0,
    htmlCharacters: defaultReferenceHtml?.length || 0,
    sectionMapEntries: defaultReferenceById?.size || 0
  });
}

export function resetLaboratoryReferenceCaches() {
  defaultReferenceSearchIndex = null; defaultReferenceHtml = null; defaultReferenceById = null;
  for (const key of Object.keys(referenceCacheMetrics)) referenceCacheMetrics[key] = 0;
}

const renderLaboratoryReferenceHtml = (sections) => {
  const toc = sections.map((section) => `<a href="#reference-${section.id}">${section.title}</a>`).join("");
  const articles = sections.map((section, index) => `<article id="reference-${section.id}" class="reference-article" data-reference-search="${`${section.title} ${section.summary}`.toLowerCase()}"><header><span>${index + 1}</span><div><h3>${section.title}</h3><p>${section.summary}</p></div></header><div class="reference-article-body">${section.html}</div><a class="reference-back" href="#laboratory-reference-top">Back to contents ↑</a></article>`).join("");
  return `<div id="laboratory-reference-top" class="laboratory-reference"><label class="reference-search"><span>Search this reference</span><input id="laboratory-reference-search" type="search" placeholder="e.g. muscle glycogen, nursing, hydration" autocomplete="off"></label><nav class="reference-toc" aria-label="Reference contents"><h3>Contents</h3>${toc}</nav><p id="laboratory-reference-empty" class="reference-empty" hidden>No reference sections match this search.</p>${articles}</div>`;
};

/** Full HTML is cached; callers may also request a canonical section subset. */
export function laboratoryReferenceHtml({ sectionIds = null } = {}) {
  if (sectionIds == null) {
    if (!defaultReferenceHtml) { defaultReferenceHtml = renderLaboratoryReferenceHtml(LABORATORY_REFERENCE_SECTIONS); referenceCacheMetrics.htmlBuilds += 1; }
    else referenceCacheMetrics.htmlHits += 1;
    return defaultReferenceHtml;
  }
  const allowed = new Set([...sectionIds].map(String));
  return renderLaboratoryReferenceHtml(LABORATORY_REFERENCE_SECTIONS.filter((section) => allowed.has(section.id)));
}
